export const LATIN_KEPT=new Set(`aids al am ap apec arsenal asean associated aston atm bangkok big blackburn bts cc0 celentano chelsea city convenience crystal cv daeng din ealing earth eleven ems eq eria et ev everton examiner forex gdp forest gen ham harvard hiv hotspur idpc ikigai imf in8b.life ipswich iq journal l-2026 layers leeds leicester life2-card.png life2.0 line-art-animation liverpool mae manchester medicine meethom mm mrt natural nesdc newcastle noi norwich nottingham organization palace pbs plos poapongsakorn post press promptpay ptt qr republished robotics rovers sanzo seap seato sec set sheffield sims southampton sripa taipei talat tcas tdri thai thaiger thailand thammasat timeline times tokaido topline tottenham town tv united universe us usb utc v2026.1 vcd vhs via villa vroid wada watford wednesday west wikipedia world zipmex anan art bank beam boonmee chanthira dao fah golf kanya khao kittisak malee may mek mint narong nok nonglak nont oak pim ploy prasert preecha ratana somchai somporn somsak suda sunee thaworn ton wichai wilai yupin`.split(/\s+/));
